(function(){if(!defined.document){return}var onErrorFnPrev=window.onerror;window.onerror=function(error,filePath,linerNr){var ret=false;if(onErrorFnPrev){ret=onErrorFnPrev(error,filePath,linerNr)}if(ret!==true){if(QUnit.config.current){if(QUnit.config.current.ignoreGlobalErrors){return true}QUnit.pushFailure(error,filePath+":"+linerNr)}else{QUnit.test("global failure",extend(function(){QUnit.pushFailure(error,filePath+":"+linerNr)},{validTest:true}))}return false}return ret}})();